"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[46342],{46342:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/too-loud-a-solitude.png\\"\\n          title=\\"Too Loud a Solitude\\"\\n          author=\\"Bohumil Hrabal\\"\\n          publisher=\\"Munhakdongne\\"\\n          publishedDate=\\"2016-07-08\\"\\n          isbn=\\"9788954641548\\"\\n          rating=4.5\\n          tags=\\"novel\\"\\n        />\\n</center>\\n\\n## Review\\nTo be honest, I read through the beginning of the book without fully understanding the content.  \\nBut gradually, I began to feel the protagonist\'s <mark>solitude</mark>.  \\nI love the title of the book. It clearly reflects what the book is trying to convey.  \\n<br>\\nIt\'s a book that reminds me of ```No Country for Old Men```.  \\n<br>\\nWith the arrival of the AI era, I am also feeling similar emotions.  \\n<br>\\nA recommended book for me that I\'d like to read again if I get the chance."}')}}]);